sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?director (COALESCE(?dbpDeath, ?dboDeath) AS ?deathDate)
WHERE {
  VALUES ?film { dbr:They_Who_Dare dbr:False_Pretenses }

  { ?film dbp:director ?director . }
  UNION
  { ?film dbo:director ?director . }

  OPTIONAL { ?director dbp:deathDate ?dbpDeath . }
  OPTIONAL { ?director dbo:deathDate ?dboDeath . }
}
LIMIT 100

